unsigned char* encode_bin(const char* input, size_t* out_len, int* err){
  if(!input){ *err=1; *out_len=0; return NULL; }
  size_t n = strlen(input);
  unsigned char* buf = (unsigned char*)malloc(n*2);
  if(!buf){ *err=2; *out_len=0; return NULL; }
  for(size_t i=0; i<n; ++i){
